import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCount } from "../src/parse.mjs";

test("parses a valid non-negative integer", () => {
  assert.equal(parseCount("0"), 0);
  assert.equal(parseCount("42"), 42);
  assert.equal(parseCount(" 7 "), 7);
});

test("rejects non-strings with TypeError", () => {
  assert.throws(() => parseCount(42), TypeError);
  assert.throws(() => parseCount(null), TypeError);
  assert.throws(() => parseCount(undefined), TypeError);
});

test("rejects invalid numbers with RangeError", () => {
  for (const bad of ["", "  ", "-1", "1.5", "abc", "12x", "0x10", "1e3"]) {
    assert.throws(() => parseCount(bad), RangeError, `expected RangeError for ${JSON.stringify(bad)}`);
  }
});
